21	/**
22	 * H2 集成测试基类：
23	 * 每个场景前按外键安全顺序清空数据，避免顺序依赖；时钟默认重置到场景起点。
24	 */
25	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
26	@Import(FixedClockTestConfig.class)
27	public abstract class AbstractH2IntegrationTest {
28	
29	    @Autowired
30	    protected JdbcTemplate jdbc;
31	    @Autowired
32	    protected TestRestTemplate rest;
33	    @LocalServerPort
34	    protected int port;
35	
36	    @BeforeEach
37	    void cleanDatabase() {
38	        jdbc.update("DELETE FROM survey_event");
39	        jdbc.update("DELETE FROM defect");
40	        jdbc.update("DELETE FROM certificate");
41	        jdbc.update("DELETE FROM extension_request");
42	        jdbc.update("DELETE FROM survey");
43	        jdbc.update("DELETE FROM idempotent_record");
44	        jdbc.update("DELETE FROM window_ledger");
45	        jdbc.update("DELETE FROM ship");
46	        FixedClockTestConfig.CLOCK.setUtcDate(defaultClockDate());
47	    }
48	
49	    /** 场景默认时钟日（UTC），子类可覆盖。 */
50	    protected LocalDate defaultClockDate() {
51	        return LocalDate.of(2026, 6, 15);
52	    }
53	
54	    protected void setClockDate(LocalDate date) {
55	        FixedClockTestConfig.CLOCK.setUtcDate(date);
56	    }
57	
58	    protected String url(String path) {
59	        return "http://localhost:" + port + path;
60	    }
61	
62	    protected static java.time.Instant instantOf(LocalDate date) {
63	        return date.atStartOfDay(ZoneOffset.UTC).toInstant();
64	    }
65	
66	    protected JsonNode post(String path, Object body) {
67	        HttpHeaders headers = new HttpHeaders();
68	        headers.setContentType(MediaType.APPLICATION_JSON);
69	        ResponseEntity<String> response = rest.postForEntity(
70	                url(path), new HttpEntity<>(body, headers), String.class);
71	        try {
72	            return new ObjectMapper().readTree(response.getBody());
73	        } catch (Exception e) {
74	            throw new IllegalStateException("响应解析失败: " + response.getBody(), e);
75	        }
76	    }
77	
78	    protected JsonNode get(String path) {
79	        ResponseEntity<String> response = rest.getForEntity(url(path), String.class);
80	        try {
81	            return new ObjectMapper().readTree(response.getBody());
82	        } catch (Exception e) {
83	            throw new IllegalStateException("响应解析失败: " + response.getBody(), e);
84	        }
85	    }
86	
87	    protected ResponseEntity<String> postRaw(String path, Object body) {
88	        HttpHeaders headers = new HttpHeaders();
89	        headers.setContentType(MediaType.APPLICATION_JSON);
90	        return rest.postForEntity(url(path), new HttpEntity<>(body, headers), String.class);
91	    }
92	
93	    protected JsonNode postExpectStatus(String path, Object body, int expectedStatus) {
94	        ResponseEntity<String> response = postRaw(path, body);
95	        if (response.getStatusCode().value() != expectedStatus) {
96	            throw new AssertionError("期望 HTTP " + expectedStatus + "，实际 HTTP "
97	                    + response.getStatusCode().value() + "，响应: " + response.getBody());
98	        }
99	        try {
100	            return new ObjectMapper().readTree(response.getBody());
101	        } catch (Exception e) {
102	            throw new IllegalStateException("响应解析失败: " + response.getBody(), e);
103	        }
