1	package com.example.starter.survey.service;
2	
3	import com.example.starter.survey.data.ShipRepository;
4	import com.example.starter.survey.data.SurveyEventRepository;
5	import com.example.starter.survey.data.SurveyRepository;
6	import com.example.starter.survey.data.DefectRepository;
7	import com.example.starter.survey.domain.Defect;
8	import com.example.starter.survey.domain.Ship;
9	import com.example.starter.survey.domain.Survey;
10	import com.example.starter.survey.domain.SurveyStatus;
11	import com.example.starter.survey.domain.SurveyType;
12	import com.example.starter.survey.support.Fingerprint;
13	import com.example.starter.survey.support.IdempotentExecutor;
14	import com.example.starter.survey.support.SurveyWindowCalculator;
15	import com.example.starter.survey.support.SurveyWindowCalculator.SurveyWindow;
16	import com.example.starter.survey.web.BusinessRuleException;
17	import com.example.starter.survey.web.ConflictException;
18	import com.example.starter.survey.web.NotFoundException;
19	import com.example.starter.survey.web.dto.ApiResult;
20	import com.example.starter.survey.web.dto.ApplySurveyRequest;
21	import com.example.starter.survey.web.dto.BoardResponse;
22	import com.example.starter.survey.web.dto.BoardSurveyRequest;
23	import com.example.starter.survey.web.dto.DefectInput;
24	import com.example.starter.survey.web.dto.DefectResponse;
25	import com.example.starter.survey.web.dto.SurveyResponse;
26	import org.springframework.stereotype.Service;
27	
28	import java.time.LocalDate;
29	import java.util.LinkedHashMap;
30	import java.util.List;
31	import java.util.Map;
32	
33	/** 检验申请受理与登轮检验。 */
34	@Service
35	public class SurveyService {
36	
37	    /** 签发终态后迟到登轮记录的事件类型。 */
38	    public static final String EVENT_LATE_BOARD_RECORD = "LATE_BOARD_RECORD";
39	
40	    private final SurveyRepository surveyRepository;
41	    private final ShipRepository shipRepository;
42	    private final DefectRepository defectRepository;
43	    private final SurveyEventRepository eventRepository;
44	    private final IdempotentExecutor executor;
45	
46	    public SurveyService(SurveyRepository surveyRepository,
47	                         ShipRepository shipRepository,
48	                         DefectRepository defectRepository,
49	                         SurveyEventRepository eventRepository,
50	                         IdempotentExecutor executor) {
51	        this.surveyRepository = surveyRepository;
52	        this.shipRepository = shipRepository;
53	        this.defectRepository = defectRepository;
54	        this.eventRepository = eventRepository;
55	        this.executor = executor;
56	    }
57	
58	    /**
59	     * 申请检验（计划→申请）。受理条件（UTC 日界）：
60	     * 今天落在该类型当前窗口闭区间内（恰在窗口首日/末日均可）；
61	     * 同船同类型无其他进行中检验（唯一索引兜底，并发唯一受理）。
62	     */
63	    public ApiResult<SurveyResponse> apply(ApplySurveyRequest request) {
64	        Ship ship = shipRepository.findByImo(request.shipImo())
65	                .orElseThrow(() -> new NotFoundException("SHIP_NOT_FOUND",
66	                        "船舶不存在: " + request.shipImo()));
67	        SurveyType type = request.type();
68	
69	        String fp = Fingerprint.of(request.requestId(), "APPLY_SURVEY",
70	                Map.of("shipImo", request.shipImo(), "type", type.name()));
71	        return executor.run(request.requestId(), fp, SurveyResponse.class, () -> {
72	            LocalDate nowUtc = LocalDate.ofInstant(executor.now(), java.time.ZoneOffset.UTC);
73	            SurveyWindow window = SurveyWindowCalculator
74	                    .windowContaining(ship, type, nowUtc)
75	                    .orElseThrow(() -> new BusinessRuleException("OUTSIDE_WINDOW",
76	                            "当前日期不在" + typeName(type) + "检验窗口内（UTC，首尾含当日）"));
77	            surveyRepository.findInProgress(ship.id(), type).ifPresent(s -> {
78	                throw new ConflictException("SURVEY_IN_PROGRESS",
79	                        "同一船舶同一检验类型已有进行中检验: surveyId=" + s.id());
80	            });
81	            try {
82	                Survey survey = surveyRepository.insert(
83	                        request.requestId(), ship.id(), type,
84	                        window.anchor(), window.start(), window.end(),
85	                        fp, executor.now());
86	                return SurveyResponse.from(survey, ship.imo());
87	            } catch (SurveyRepository.ActiveSurveyConflict e) {
88	                throw new ConflictException("SURVEY_IN_PROGRESS",
89	                        "并发申请：同一船舶同一检验类型仅受理一个进行中检验");
90	            }
91	        });
92	    }
93	
94	    /**
95	     * 登轮检验（申请→登轮）。完成日须落在窗口（含已批准展期末日）闭区间内。
96	     * 检验已发证（终态）后迟到的登轮记录只登记 {@link #EVENT_LATE_BOARD_RECORD} 事件。
97	     */
98	    public ApiResult<BoardResponse> board(BoardSurveyRequest request) {
99	        Survey survey = surveyRepository.findById(request.surveyId())
100	                .orElseThrow(() -> new NotFoundException("SURVEY_NOT_FOUND",
101	                        "检验不存在: surveyId=" + request.surveyId()));
102	        Ship ship = shipRepository.findById(survey.shipId()).orElseThrow();
103	
104	        Map<String, Object> fields = new LinkedHashMap<>();
105	        fields.put("surveyId", request.surveyId());
106	        fields.put("completedDate", request.completedDate().toString());
107	        fields.put("defects", request.defects() == null ? List.of()
108	                : request.defects().stream()
109	                .map(d -> Map.of("severity", d.severity().name(),
110	                        "description", d.description(),
111	                        "foundDate", d.foundDate().toString()))
112	                .toList());
113	        String fp = Fingerprint.of(request.requestId(), "BOARD_SURVEY", fields);
114	
115	        return executor.run(request.requestId(), fp, BoardResponse.class, () -> {
116	            if (survey.status() == SurveyStatus.CERTIFIED) {
117	                // 终态后迟到：只记事件，不改变状态、不产生新证书。
118	                eventRepository.insert(survey.id(), EVENT_LATE_BOARD_RECORD,
119	                        "{\"completedDate\":\"" + request.completedDate()
120	                                + "\",\"defectCount\":"
121	                                + (request.defects() == null ? 0 : request.defects().size()) + "}",
122	                        executor.now());
123	                List<DefectResponse> existing = defectRepository.findBySurvey(survey.id())
124	                        .stream().map(DefectResponse::from).toList();
125	                return new BoardResponse(SurveyResponse.from(survey, ship.imo()),
126	                        existing, true);
127	            }
128	            if (survey.status() != SurveyStatus.APPLIED) {
129	                throw new ConflictException("SURVEY_ALREADY_BOARDED",
130	                        "检验已完成登轮: surveyId=" + survey.id());
131	            }
132	            LocalDate effectiveEnd = survey.extensionUntil() != null
133	                    ? survey.extensionUntil() : survey.windowEnd();
134	            if (request.completedDate().isBefore(survey.windowStart())
135	                    || request.completedDate().isAfter(effectiveEnd)) {
136	                throw new BusinessRuleException("OUTSIDE_WINDOW",
137	                        "登轮完成日 " + request.completedDate()
138	                                + " 不在检验窗口 [" + survey.windowStart() + ", "
139	                                + effectiveEnd + "] 内（UTC，首尾含当日）");
140	            }
141	            List<DefectInput> inputs = request.defects() == null ? List.of() : request.defects();
142	            for (DefectInput d : inputs) {
143	                if (d.foundDate().isAfter(request.completedDate())) {
144	                    throw new BusinessRuleException("DEFECT_DATE_INVALID",
145	                            "缺陷发现日不得晚于登轮完成日: " + d.foundDate());
146	                }
147	            }
148	            surveyRepository.markBoarded(survey.id(), executor.now());
149	            List<DefectResponse> defects = new java.util.ArrayList<>();
150	            for (DefectInput d : inputs) {
151	                LocalDate deadline = switch (d.severity()) {
152	                    // 一般缺陷限 30 日复查（含第 30 日）；重大缺陷发证前必须完成，无固定期限。
153	                    case MINOR -> SurveyWindowCalculator.minorDeadline(d.foundDate());
154	                    case MAJOR -> null;
155	                };
156	                Defect saved = defectRepository.insert(survey.id(), d.severity(),
157	                        d.description(), d.foundDate(), deadline,
158	                        request.requestId(), fp, executor.now());
159	                defects.add(DefectResponse.from(saved));
160	            }
161	            Survey updated = surveyRepository.findById(survey.id()).orElseThrow();
162	            return new BoardResponse(SurveyResponse.from(updated, ship.imo()), defects, false);
163	        });
164	    }
