1	package com.example.starter.survey.it;
2	
3	import com.example.starter.survey.testsupport.AbstractH2IntegrationTest;
4	import com.fasterxml.jackson.databind.JsonNode;
5	import com.fasterxml.jackson.databind.ObjectMapper;
6	import org.junit.jupiter.api.Test;
7	import org.springframework.http.HttpEntity;
8	import org.springframework.http.HttpHeaders;
9	import org.springframework.http.MediaType;
10	import org.springframework.http.ResponseEntity;
11	
12	import java.time.LocalDate;
13	import java.util.List;
14	import java.util.concurrent.CountDownLatch;
15	import java.util.concurrent.ExecutorService;
16	import java.util.concurrent.Executors;
17	import java.util.concurrent.Future;
18	import java.util.concurrent.TimeUnit;
19	import java.util.stream.IntStream;
20	
21	import static org.junit.jupiter.api.Assertions.assertEquals;
22	import static org.junit.jupiter.api.Assertions.assertTrue;
23	
24	/**
25	 * 真实并发边界（H2 行锁/唯一索引验证，非 mock）：
26	 * 同船同类型并发申请唯一受理；同键并发同参唯一受理且另一请求重放；
27	 * 同一检验并发发证只产生一张有效证书。
28	 */
29	class ConcurrencyFlowTest extends AbstractH2IntegrationTest {
30	
31	    private static final LocalDate ANNIVERSARY = LocalDate.of(2020, 6, 15);
32	    private static final LocalDate DELIVERY = LocalDate.of(2020, 3, 1);
33	
34	    private void registerShip(String reqId, String imo) {
35	        postExpectStatus("/api/ships",
36	                shipBody(reqId, imo, ANNIVERSARY, DELIVERY), 200);
37	    }
38	
39	    private record HttpResult(int status, JsonNode body) {
40	    }
41	
42	    private HttpResult postSync(String path, Object body) {
43	        HttpHeaders headers = new HttpHeaders();
44	        headers.setContentType(MediaType.APPLICATION_JSON);
45	        ResponseEntity<String> response = rest.getRestTemplate()
46	                .postForEntity(url(path), new HttpEntity<>(body, headers), String.class);
47	        try {
48	            return new HttpResult(response.getStatusCode().value(),
49	                    new ObjectMapper().readTree(response.getBody()));
50	        } catch (Exception e) {
51	            throw new IllegalStateException(e);
52	        }
53	    }
54	
55	    private List<HttpResult> runParallel(int n, java.util.function.Supplier<HttpResult> task)
56	            throws Exception {
57	        ExecutorService pool = Executors.newFixedThreadPool(n);
58	        CountDownLatch ready = new CountDownLatch(n);
59	        CountDownLatch start = new CountDownLatch(1);
60	        try {
61	            List<Future<HttpResult>> futures = IntStream.range(0, n).mapToObj(i ->
62	                    pool.submit(() -> {
63	                        ready.countDown();
64	                        assertTrue(start.await(10, TimeUnit.SECONDS));
65	                        return task.get();
66	                    })).toList();
67	            assertTrue(ready.await(10, TimeUnit.SECONDS));
68	            start.countDown();
69	            List<HttpResult> results = new java.util.ArrayList<>();
70	            for (Future<HttpResult> f : futures) {
71	                results.add(f.get(30, TimeUnit.SECONDS));
72	            }
73	            return results;
74	        } finally {
75	            pool.shutdownNow();
76	        }
77	    }
78	
79	    @Test
80	    void parallelApplicationsForSameShipAndTypeOnlyOneAccepted() throws Exception {
81	        registerShip("ship-pa", "IMO-PA");
82	        setClockDate(LocalDate.of(2026, 6, 15));
83	
84	        List<HttpResult> results = runParallel(8, () ->
85	                postSync("/api/surveys",
86	                        applyBody("apply-" + java.util.UUID.randomUUID(),
87	                                "IMO-PA", "ANNUAL")));
88	
89	        long ok = results.stream().filter(r -> r.status == 200).count();
90	        long conflict = results.stream()
91	                .filter(r -> r.status == 409
92	                        && "SURVEY_IN_PROGRESS".equals(r.body.get("code").asText()))
93	                .count();
94	        assertEquals(1, ok, "恰好一个申请受理");
95	        assertEquals(7, conflict, "其余并发申请全部 409");
96	
97	        Integer surveys = jdbc.queryForObject(
98	                "SELECT COUNT(*) FROM survey WHERE ship_id="
99	                        + "(SELECT id FROM ship WHERE imo='IMO-PA')", Integer.class);
100	        assertEquals(1, surveys);
101	        Integer inProgress = jdbc.queryForObject(
102	                "SELECT COUNT(*) FROM survey WHERE ship_id="
103	                        + "(SELECT id FROM ship WHERE imo='IMO-PA') AND active_flag='Y'",
104	                Integer.class);
105	        assertEquals(1, inProgress);
106	    }
107	
108	    @Test
109	    void parallelSameRequestSameParamsAcceptedOnceOtherReplays() throws Exception {
110	        registerShip("ship-pr", "IMO-PR");
111	        setClockDate(LocalDate.of(2026, 6, 15));
112	
113	        List<HttpResult> results = runParallel(6, () ->
114	                postSync("/api/surveys",
115	                        applyBody("same-key", "IMO-PR", "ANNUAL")));
116	
117	        long first = results.stream().filter(r -> r.status == 200
118	                && !r.body.get("replayed").asBoolean()).count();
119	        long replay = results.stream().filter(r -> r.status == 200
120	                && r.body.get("replayed").asBoolean()).count();
121	        long inFlight = results.stream()
122	                .filter(r -> r.status == 409
123	                        && "IDEMPOTENCY_IN_FLIGHT".equals(r.body.get("code").asText()))
124	                .count();
125	        assertEquals(1, first, "唯一首次受理");
126	        assertEquals(5, replay + inFlight, "其余请求重放首次结果或得到处理中冲突");
127	
128	        Integer surveys = jdbc.queryForObject(
129	                "SELECT COUNT(*) FROM survey WHERE request_id='same-key'", Integer.class);
130	        assertEquals(1, surveys, "同键并发不产生多条检验");
131	        // 处理中冲突的请求随后用同参数重放，必须拿到首次结果。
132	        HttpResult later = postSync("/api/surveys",
133	                applyBody("same-key", "IMO-PR", "ANNUAL"));
134	        assertEquals(200, later.status);
135	        assertTrue(later.body.get("replayed").asBoolean());
136	    }
137	
138	    @Test
139	    void parallelCertifyProducesExactlyOneValidCertificate() throws Exception {
140	        registerShip("ship-pc", "IMO-PC");
141	        setClockDate(LocalDate.of(2026, 3, 15));
142	        JsonNode applied = postExpectStatus("/api/surveys",
143	                applyBody("ap-pc", "IMO-PC", "ANNUAL"), 200);
